page Counter "/" {
  state count = 0
  computed double = count * 2

  column gap=4 align=center pad=4 {
    title "Contador"
    row gap=4 align=center {
      button "-" -> count--
      text `${count}` bold
      button "+" primary -> count++
    }
    text `El doble es ${double}`
    if count > 5 {
      text "¡Más de 5!"
    }
  }
}

model Task {
  id: ID
  title: String
  done: Bool
}

component TaskItem(task: Task, onDelete: Fn) {
  row gap=2 align=center {
    checkbox task.done
    text task.title muted=task.done
    button "x" small danger -> onDelete(task.id)
  }
}

page Todos "/" {
  state tasks: Task[] = []
  state draft = ""

  computed pending = tasks.filter(t => !t.done).length

  fn add(title) {
    let clean = title.trim()
    if clean == "" { return }
    tasks.push({ id: crypto.randomUUID(), title: clean, done: false })
    draft = ""
  }

  fn remove(id) {
    tasks = tasks.filter(t => t.id != id)
  }

  column gap=4 pad=4 {
    title "Tareas"
    row gap=2 {
      input draft placeholder="¿Qué hay que hacer?" -> add(draft)
      button "Agregar" primary -> add(draft)
    }
    for t in tasks key t.id {
      TaskItem task=t onDelete=remove
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      text `${pending} pendientes` muted
    }
  }
}

page Login "/" {
  state email = ""
  state password = ""
  state done = false
  state sentEmail = ""

  computed valid = email.includes("@") && password.length >= 8

  fn submit() {
    if !valid { return }
    sentEmail = email
    done = true
  }

  column gap=4 pad=6 align=center {
    if done {
      title `Bienvenido, ${sentEmail}`
    } else {
      form gap=3 -> submit() {
        title "Iniciar sesión"
        input email type=email label="Email" placeholder="Email" required
        input password type=password label="Contraseña" placeholder="Contraseña" required
        button "Entrar" primary disabled=(!valid)
      }
    }
  }
}

