model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  state products: Product[] = [
    { id: "1", name: "Remera", price: 15.5 },
    { id: "2", name: "Pantalón", price: 39.99 },
    { id: "3", name: "Zapatillas", price: 89.9 }
  ]
  state cart: CartItem[] = []

  computed total = cart.reduce((s, i) => s + i.price * i.qty, 0)
  computed totalText = total.toFixed(2)

  fn add(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      found.qty++
    } else {
      cart.push({ id: p.id, name: p.name, price: p.price, qty: 1 })
    }
  }

  fn inc(i) {
    i.qty++
  }

  fn dec(i) {
    if i.qty <= 1 {
      cart = cart.filter(x => x.id != i.id)
    } else {
      i.qty--
    }
  }

  column gap=6 pad=6 {
    title "Tienda"
    card pad=4 gap=3 {
      title "Productos" small
      for p in products key p.id {
        row gap=3 align=center justify=between {
          text `${p.name} - $${p.price.toFixed(2)}`
          button "Agregar" primary small -> add(p)
        }
      }
    }
    card pad=4 gap=3 {
      title "Carrito" small
      if cart.length == 0 {
        text "El carrito está vacío" muted
      } else {
        for i in cart key i.id {
          row gap=3 align=center justify=between {
            text `${i.name} - $${i.price.toFixed(2)}`
            row gap=2 align=center {
              button "-" small -> dec(i)
              text `${i.qty}` bold
              button "+" small -> inc(i)
            }
          }
        }
      }
      divider
      text `Total: $${totalText}` bold large
    }
  }
}

