model User {
  id: ID
  name: String min=1
  email: String
}

api users: User

page Users "/" {
  state name = ""
  state email = ""
  state error = ""

  data users = api.users.list()

  fn add() {
    if !email.includes("@") {
      error = "Email inválido"
      return
    }
    error = ""
    try {
      api.users.create({ name: name, email: email })
      name = ""
      email = ""
    } catch (e) {
      error = e.message
    }
  }

  fn del(id) {
    api.users.remove(id)
  }

  column gap=4 pad=4 {
    title "Usuarios"
    row gap=2 wrap {
      input name placeholder="Nombre"
      input email placeholder="Email"
      button "Agregar" primary -> add()
    }
    if error != "" {
      text error danger
    }
    for u in users key u.id {
      card pad=3 {
        row gap=3 align=center justify=between {
          column gap=1 {
            text u.name bold
            text u.email muted
          }
          button "Borrar" danger small -> del(u.id)
        }
      }
    }
  }
}

model Item {
  id: ID
  name: String min=1 max=100
  bought: Bool = false
}

api items: Item

page Shopping "/" {
  state draft = ""
  data items = api.items.list()
  data pending = api.items.count({ where: { bought: false } })

  fn add(name) {
    let n = name.trim()
    if n == "" { return }
    api.items.create({ name: n, bought: false })
    draft = ""
  }

  fn buy(item) {
    api.items.update(item.id, { bought: true })
  }

  fn del(item) {
    api.items.remove(item.id)
  }

  column gap=4 pad=4 {
    title "Lista de compras"
    text `${pending} por comprar`
    row gap=2 {
      input draft placeholder="Producto" -> add(draft)
      button "Agregar" primary -> add(draft)
    }
    if items.length == 0 {
      text "No hay productos" muted
    } else {
      column gap=2 {
        for item in items key item.id {
          row gap=2 align=center {
            text item.bought ? `${item.name} ✓` : item.name
            button "Comprado" small disabled=item.bought -> buy(item)
            button "Borrar" small danger -> del(item)
          }
        }
      }
    }
  }
}

