model Product {
  id: ID
  name: String min=3
  code: String unique
  price: Number min=0
}

api products: Product

page Home "/" {
  state name = ""
  state code = ""
  state price = ""
  state error = ""

  data products = api.products.list()

  fn save() {
    error = ""
    if name.trim().length < 3 {
      error = "Nombre muy corto"
      return
    }
    let p = Number(price)
    if price == "" || isNaN(p) || p < 0 {
      error = "Precio inválido"
      return
    }
    let existing = products.find(x => x.code == code)
    if existing {
      error = "Código repetido"
      return
    }
    try {
      await api.products.create({ name: name.trim(), code: code, price: p })
      name = ""
      code = ""
      price = ""
    } catch (e) {
      let m = String(e.message).toLowerCase()
      if m.includes("unique") || m.includes("exist") || m.includes("code") || m.includes("código") {
        error = "Código repetido"
      } else if m.includes("price") || m.includes("precio") {
        error = "Precio inválido"
      } else {
        error = "Nombre muy corto"
      }
    }
  }

  column gap=4 pad=4 {
    title "Productos"
    input name placeholder="Nombre"
    input code placeholder="Código"
    input price placeholder="Precio" type=number
    button "Guardar" primary -> save()
    if error != "" {
      text error danger
    }
    for p in products key p.id {
      card pad=3 {
        text p.name bold
        text p.code muted
      }
    }
  }
}

model Profile {
  id: ID
  photo: File? max=5000000 accept="image/*"
}

api profiles: Profile

page Profile "/" {
  state picked: File? = null
  state busy = false

  data items = api.profiles.list()
  computed current = items.length > 0 ? items[0] : null

  fn upload() {
    if !picked { return }
    busy = true
    try {
      if current {
        await api.profiles.update(current.id, { photo: picked })
      } else {
        await api.profiles.create({ photo: picked })
      }
      picked = null
      notify("Foto subida", "success")
    } catch (e) {
      notify(e.message, "danger")
    }
    busy = false
  }

  column gap=4 pad=6 {
    title "Perfil"
    file picked accept="image/*" label="Foto"
    button "Subir" primary disabled=(!picked || busy) -> upload()
    if current && current.photo {
      image current.photo.url alt="Foto de perfil" width=200
    } else {
      text "Todavía no hay foto" muted
    }
  }
}

