page Cronometro "/" {
  state n = 0
  state timer = null

  fn start() {
    if timer != null { return }
    timer = setInterval(() => { n++ }, 100)
  }

  fn pause() {
    if timer != null {
      clearInterval(timer)
      timer = null
    }
  }

  fn reset() {
    pause()
    n = 0
  }

  mount {
    cleanup {
      if timer != null { clearInterval(timer) }
    }
  }

  column gap=4 pad=4 align=center {
    title `Tiempo: ${n}`
    row gap=2 {
      button "Iniciar" primary -> start()
      button "Pausar" -> pause()
      button "Reiniciar" danger -> reset()
    }
  }
}

