  state done = false

  fn next1() {
    if name.trim() == "" {
      error = "Nombre requerido"
      return
    }
    error = ""
    step = 2
  }

  fn back() {
    step--
  }

  fn next2() {
    step = 3
  }

  fn confirm() {
    done = true
  }

  column gap=4 pad=4 {
    if done {
      title `¡Listo, ${name}!`
    } else {
      text `Paso ${step} de 3` bold
      if step == 1 {
        input name placeholder="Nombre" -> next1()
        if error != "" {
          text error danger
        }
        button "Siguiente" primary -> next1()
      }
      if step == 2 {
        select plan options=["Gratis", "Pro"] label="Plan"
        checkbox news label="Recibir novedades"
        row gap=2 {
          button "Atrás" -> back()
          button "Siguiente" primary -> next2()
        }
      }
      if step == 3 {
        text `${name} eligió ${plan}`
        if news {
          text "Con novedades"
        }
        row gap=2 {
          button "Atrás" -> back()
          button "Confirmar" primary -> confirm()
        }
      }
    }
  }
}

