model Task {
  id: ID
  title: String min=1
  done: Bool = false
}

api tasks: Task

page Tasks "/" {
  state draft = ""
  state filter = "Todas"
  state editingId = ""
  state newTitle = ""

  data tasks = api.tasks.list()

  computed visible = tasks.filter(t => filter == "Todas" ? true : (filter == "Pendientes" ? !t.done : t.done))

  fn add() {
    if draft == "" { return }
    api.tasks.create({ title: draft, done: false })
    draft = ""
  }

  fn markDone(t) {
    api.tasks.update(t.id, { done: true })
  }

  fn startEdit(t) {
    editingId = t.id
    newTitle = t.title
  }

  fn save(t) {
    if newTitle == "" { return }
    api.tasks.update(t.id, { title: newTitle })
    editingId = ""
    newTitle = ""
  }

  column gap=4 pad=4 {
    title "Tareas"
    row gap=2 {
      input draft placeholder="Tarea" -> add()
      button "Agregar" primary -> add()
    }
    select filter options=["Todas", "Pendientes", "Hechas"] label="Filtro"
    for t in visible key t.id {
      row gap=2 align=center {
        if editingId == t.id {
          input newTitle placeholder="Nuevo título" -> save(t)
          button "Guardar" -> save(t)
        } else {
          text t.title
          if t.done {
            text "(hecha)"
          }
          if !t.done {
            button "Hecha" -> markDone(t)
          }
          button "Renombrar" -> startEdit(t)
        }
      }
    }
  }
}

model Vote {
